<?php require_once __DIR__.'/bootstrap.php';$id=(int)($_GET['id']??0);$s=$pdo->prepare('SELECT a.*,GROUP_CONCAT(DISTINCT g.name SEPARATOR ", ") genres FROM anime a LEFT JOIN anime_genres ag ON ag.anime_id=a.id LEFT JOIN genres g ON g.id=ag.genre_id WHERE a.id=? GROUP BY a.id');$s->execute([$id]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Anime not found');}$title=$a['title'].' — AniRead';$description=mb_strimwidth($a['synopsis']??'Discover '.$a['title'].' on AniRead.',0,160,'…');include __DIR__.'/includes/header.php';?><section class="detail"><img class="poster" src="<?=e($a['poster']?:'assets/placeholder.svg')?>" alt="<?=e($a['title'])?>"><div><span class="eyebrow"><?=e($a['type'])?></span><h1><?=e($a['title'])?></h1><?php if($a['english_title']&&$a['english_title']!==$a['title']):?><p class="muted"><?=e($a['english_title'])?></p><?php endif;?><p class="muted"><?=e($a['synopsis'])?></p><div class="meta">★ <?=e($a['score']?:'—')?> · <?=e($a['status']?:'—')?> · <?=e($a['year']?:'—')?> · <?=e($a['episodes']?:'—')?> eps</div><p>Genres: <?=e($a['genres']?:'—')?></p><div class="actions"><a class="btn" href="<?=url('watch.php?id='.$id)?>">Watch Now</a><?php if(user()):?><form method="post" action="<?=url('watchlist.php')?>"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="anime_id" value="<?=$id?>"><button class="btn alt">Add to Watchlist</button></form><?php endif;?></div></div></section><section class="section"><h2>Episodes</h2><div class="episode-list"><?php $es=$pdo->prepare('SELECT * FROM episodes WHERE anime_id=? AND active=1 ORDER BY number');$es->execute([$id]);foreach($es as $ep):?><a href="<?=url('watch.php?id='.$id.'&episode='.urlencode($ep['number']))?>">Episode <?=e($ep['number'])?></a><?php endforeach;?></div></section><?php include __DIR__.'/includes/footer.php';
